-- The imported entries already occupy AR-2026-00001 upward, so the sequence has
-- to continue past them. Without this, the first collection somebody creates
-- collides with an imported row and the insert fails.
INSERT OR IGNORE INTO erp_sequences(code,next_value,prefix,width)
  VALUES('AR_COLLECTION',1,'AR-2026',5);
UPDATE erp_sequences
   SET next_value = (SELECT COUNT(*)+1 FROM erp_ar_collections WHERE entry_no LIKE 'AR-2026-%')
 WHERE code='AR_COLLECTION'
   AND next_value <= (SELECT COUNT(*) FROM erp_ar_collections WHERE entry_no LIKE 'AR-2026-%');
